      gb[4] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[5] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+2)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[6] = (c_lex[12+pj+0]*3 + c_lex[12+pk+0]*9 + c_lex[3+pl+0]*27)*NSQ + 0*g_size*NSQ;
      gb[7] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[8] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
