      gb[13] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[14] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+5)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[15] = (c_lex[12+pj+0]*3 + c_lex[12+pk+0]*9 + c_lex[3+pl+0]*27)*NSQ + 0*g_size*NSQ;
      gb[16] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[17] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[18] = (c_lex[12+pj+0]*3 + c_lex[12+pk+0]*9 + c_lex[3+pl+0]*27)*NSQ + 0*g_size*NSQ;
      gb[19] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[20] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+1)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[21] = (c_lex[12+pj+0]*3 + c_lex[12+pk+0]*9 + c_lex[3+pl+0]*27)*NSQ + 0*g_size*NSQ;
      gb[22] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[23] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+2)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[24] = (c_lex[12+pj+0]*3 + c_lex[12+pk+0]*9 + c_lex[3+pl+0]*27)*NSQ + 0*g_size*NSQ;
      gb[25] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[26] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+3)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[27] = (c_lex[12+pj+0]*3 + c_lex[12+pk+0]*9 + c_lex[3+pl+0]*27)*NSQ + 0*g_size*NSQ;
      gb[28] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[29] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+4)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[30] = (c_lex[12+pj+0]*3 + c_lex[12+pk+0]*9 + c_lex[3+pl+0]*27)*NSQ + 0*g_size*NSQ;
      gb[31] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[32] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+5)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[33] = (c_lex[12+pj+0]*3 + c_lex[12+pk+0]*9 + c_lex[3+pl+0]*27)*NSQ + 0*g_size*NSQ;
      gb[34] = (c_lex[12+pj+1]*3 + c_lex[12+pk+1]*9 + c_lex[3+pl+1]*27)*NSQ + 1*g_size*NSQ;
      gb[35] = (c_lex[12+pj+2]*3 + c_lex[12+pk+2]*9 + c_lex[3+pl+2]*27)*NSQ + 2*g_size*NSQ;
    }
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += NSQ) {
        __syncthreads();
        int kprim = kprim_a;
        int lprim = lprim_a;
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        if (gout_id == 0) {
            rlrk[0*NSQ] = rl[0] - rk[0];
            rlrk[1*NSQ] = rl[1] - rk[1];
            rlrk[2*NSQ] = rl[2] - rk[2];
            fac_ijkl[0] = fac_sym;
        }
        double gout[72];
#pragma unroll
        for (int n = 0; n < 72; ++n) gout[n] = 0.;

        for (int klp = 0; klp < kprim*lprim; ++klp) {
            __syncthreads();
            if (gout_id == 0) {
                double *expk = env + bas[ksh*BAS_SLOTS+PTR_EXP];
                double *expl = env + bas[lsh*BAS_SLOTS+PTR_EXP];
                double *ck = env + bas[ksh*BAS_SLOTS+PTR_COEFF];
                double *cl = env + bas[lsh*BAS_SLOTS+PTR_COEFF];
                double ak = expk[klp/lprim];
                double al = expl[klp%lprim];
                double akl = ak + al;
                double iakl = 1. / akl;
                double al_akl = al * iakl;
                double xlxk = rlrk[0*NSQ], ylyk = rlrk[1*NSQ], zlzk = rlrk[2*NSQ];
                double Kcd = exp(-ak * al_akl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                gx[0] = fac_ijkl[0] * ck[klp/lprim] * cl[klp%lprim] * Kcd;
                akl_cache[0*NSQ] = akl;
                akl_cache[1*NSQ] = al_akl;
                akl_cache[2*NSQ] = iakl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                __syncthreads();
                double aij = s_aij[ijp];
                double iaij = s_iaij[ijp];
                double akl = akl_cache[0*NSQ];
                double al_akl = akl_cache[1*NSQ];
                double iakl = akl_cache[2*NSQ];
                // Range separation: inv_om2 = 0 is the full-range operator,
                // 1/omega^2 the long-range (erf) one -- scaling the Rys
                // argument and roots by w^2/(w^2+theta) is exactly
                // rsqrt(s) -> rsqrt(s + aij*akl/w^2) here.
                double inv_s = rsqrt(fma(aij * akl, inv_om2, aij + akl));
                double inv_s2 = inv_s * inv_s;
                double xkl = rk[0] + rlrk[0*NSQ] * al_akl;
                double ykl = rk[1] + rlrk[1*NSQ] * al_akl;
                double zkl = rk[2] + rlrk[2*NSQ] * al_akl;
                double xpq = s_xij[ijp] - xkl;
                double ypq = s_yij[ijp] - ykl;
                double zpq = s_zij[ijp] - zkl;
                if (gout_id == 0) {
                    Rpq[0*NSQ] = xpq;
                    Rpq[1*NSQ] = ypq;
                    Rpq[2*NSQ] = zpq;
                    // fac = cicj*ckcl/(aij*akl*sqrt(aij+akl)), no division
                    gx[NSQ*g_size] = s_cicj[ijp] * iaij * iakl * inv_s * coef0;
                }
                double rr = xpq*xpq + ypq*ypq + zpq*zpq;
                rys_roots_tab<NROOTS>(aij*akl*inv_s2 * rr, rw, NSQ, gout_id,
                                      GSTRIDE, tab);
                for (int irys = 0; irys < NROOTS; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[2*irys*NSQ];
                    double rt_aa = rt * inv_s2;
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5*iaij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5*iakl * (1 - rt_akl);
                    (void)b10; (void)b00; (void)b01;
                    for (int n = gout_id; n < 3; n += GSTRIDE) {
                        if (n == 2) { gx[2*g_size*NSQ] = rw[(2*irys+1)*NSQ]; }
                        double *_gx = gx + n * g_size * NSQ;
                        double xjxi = rjri[n], xlxk = rlrk[n*NSQ];
                        double c0x = xjxi * s_ajaij[ijp] - rt_aij * Rpq[n*NSQ];
                        double cpx = xlxk * al_akl + rt_akl * Rpq[n*NSQ];
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = _gx[0*NSQ];
                        s1 = c0x * s0;
                        _gx[1*NSQ] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[0*NSQ];
                        s1 = cpx * s0;
                        _gx[9*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        _gx[18*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        _gx[27*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[1*NSQ];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0*NSQ];
                        _gx[10*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 1 * b00 * _gx[9*NSQ];
                        _gx[19*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 1 * b00 * _gx[18*NSQ];
                        _gx[28*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[2*NSQ];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1*NSQ];
                        _gx[11*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 2 * b00 * _gx[10*NSQ];
                        _gx[20*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 2 * b00 * _gx[19*NSQ];
                        _gx[29*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[3*NSQ];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2*NSQ];
                        _gx[12*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 3 * b00 * _gx[11*NSQ];
                        _gx[21*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 3 * b00 * _gx[20*NSQ];
                        _gx[30*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[4*NSQ];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[3*NSQ];
                        _gx[13*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 4 * b00 * _gx[12*NSQ];
                        _gx[22*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 4 * b00 * _gx[21*NSQ];
                        _gx[31*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s1 = _gx[4*NSQ];
                        s0 = _gx[3*NSQ];
                        _gx[6*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[2*NSQ];
                        _gx[5*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[1*NSQ];
