// ---- (3011) : 90 gout over 1 lanes, 64 shell quartets per block
#define NTHREADS_3011 64
#define MINBLOCKS_3011 1
extern "C" __global__ void __launch_bounds__(NTHREADS_3011, MINBLOCKS_3011)
kh_3011(KARGS2)
{
    constexpr int NSQ = 64;
    constexpr int GSTRIDE = 1;
    constexpr int NROOTS = 3;
    constexpr int g_size = 16;
    constexpr int nsq_per_block = NSQ;
    __shared__ double s_aij[36], s_iaij[36], s_ajaij[36];
    __shared__ double s_xij[36], s_yij[36], s_zij[36];
    __shared__ double s_cicj[36];

    int sq_id = threadIdx.x;
    int gout_id = threadIdx.y;
    int thread_id = NSQ * gout_id + sq_id;
    constexpr int threads = NSQ * GSTRIDE;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    __shared__ int ntasks, pair_ij;
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
    }
    __syncthreads();
    fill_vk_tasks2(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff);
    if (ntasks == 0) {
        if (thread_id == 0) {
            pair_ij = atomicAdd(head, 1);
        }
        __syncthreads();
        continue;
    }

    extern __shared__ double shared_memory[];
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + NSQ * 3 + sq_id;
    double *akl_cache = shared_memory + NSQ * 6 + sq_id;
    double *fac_ijkl = shared_memory + NSQ * 9 + sq_id;
    double *gx = shared_memory + NSQ * 10 + sq_id;
    double *rw = shared_memory + NSQ * (g_size*3+10) + sq_id;

    __shared__ int ish, jsh;
    __shared__ double ri[3], rjri[3];
    __shared__ double *expi;
    __shared__ double *expj;
    if (thread_id == 0) {
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
        expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a;
    int jprim = jprim_a;
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
    for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
        double ai = expi[ij/jprim];
        double aj = expj[ij%jprim];
        double aij = ai + aj;
        double iaij = 1. / aij;
        double aj_aij = aj * iaij;
        s_aij  [ij] = aij;
        s_iaij [ij] = iaij;
        s_ajaij[ij] = aj_aij;
        s_xij  [ij] = ri[0] + rjri[0] * aj_aij;
        s_yij  [ij] = ri[1] + rjri[1] * aj_aij;
        s_zij  [ij] = ri[2] + rjri[2] * aj_aij;
        s_cicj [ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
    }
    __syncthreads();
    int o_base = gout_id * 9;
    int jb_ = o_base % 1;
    int kb_ = (o_base / 1) % 3;
    int lb_ = o_base / 3;
    int gb[27];
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[0] = (c_lex[0+pj+0]*4 + c_lex[3+pk+0]*4 + c_lex[3+pl+0]*8)*NSQ + 0*g_size*NSQ;
      gb[1] = (c_lex[0+pj+1]*4 + c_lex[3+pk+1]*4 + c_lex[3+pl+1]*8)*NSQ + 1*g_size*NSQ;
      gb[2] = (c_lex[0+pj+2]*4 + c_lex[3+pk+2]*4 + c_lex[3+pl+2]*8)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[3] = (c_lex[0+pj+0]*4 + c_lex[3+pk+0]*4 + c_lex[3+pl+0]*8)*NSQ + 0*g_size*NSQ;
      gb[4] = (c_lex[0+pj+1]*4 + c_lex[3+pk+1]*4 + c_lex[3+pl+1]*8)*NSQ + 1*g_size*NSQ;
      gb[5] = (c_lex[0+pj+2]*4 + c_lex[3+pk+2]*4 + c_lex[3+pl+2]*8)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+2)*3, pl = (lb_+0)*3;
      gb[6] = (c_lex[0+pj+0]*4 + c_lex[3+pk+0]*4 + c_lex[3+pl+0]*8)*NSQ + 0*g_size*NSQ;
      gb[7] = (c_lex[0+pj+1]*4 + c_lex[3+pk+1]*4 + c_lex[3+pl+1]*8)*NSQ + 1*g_size*NSQ;
      gb[8] = (c_lex[0+pj+2]*4 + c_lex[3+pk+2]*4 + c_lex[3+pl+2]*8)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+1)*3;
      gb[9] = (c_lex[0+pj+0]*4 + c_lex[3+pk+0]*4 + c_lex[3+pl+0]*8)*NSQ + 0*g_size*NSQ;
      gb[10] = (c_lex[0+pj+1]*4 + c_lex[3+pk+1]*4 + c_lex[3+pl+1]*8)*NSQ + 1*g_size*NSQ;
      gb[11] = (c_lex[0+pj+2]*4 + c_lex[3+pk+2]*4 + c_lex[3+pl+2]*8)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+1)*3, pl = (lb_+1)*3;
      gb[12] = (c_lex[0+pj+0]*4 + c_lex[3+pk+0]*4 + c_lex[3+pl+0]*8)*NSQ + 0*g_size*NSQ;
      gb[13] = (c_lex[0+pj+1]*4 + c_lex[3+pk+1]*4 + c_lex[3+pl+1]*8)*NSQ + 1*g_size*NSQ;
