            val += gout[15] * dm[(ii+5)*nao+(llx+0)];
            val += gout[16] * dm[(ii+6)*nao+(llx+0)];
            val += gout[17] * dm[(ii+7)*nao+(llx+0)];
            val += gout[18] * dm[(ii+8)*nao+(llx+0)];
            val += gout[19] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+0)*nao+(kk+1), val);
            val = 0;
            val += gout[20] * dm[(ii+0)*nao+(llx+0)];
            val += gout[21] * dm[(ii+1)*nao+(llx+0)];
            val += gout[22] * dm[(ii+2)*nao+(llx+0)];
            val += gout[23] * dm[(ii+3)*nao+(llx+0)];
            val += gout[24] * dm[(ii+4)*nao+(llx+0)];
