      gb[22] = (c_lex[3+pj+1]*4 + c_lex[3+pk+1]*8 + c_lex[3+pl+1]*16)*NSQ + 1*g_size*NSQ;
      gb[23] = (c_lex[3+pj+2]*4 + c_lex[3+pk+2]*8 + c_lex[3+pl+2]*16)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+2)*3, pk = (kb_+2)*3, pl = (lb_+0)*3;
      gb[24] = (c_lex[3+pj+0]*4 + c_lex[3+pk+0]*8 + c_lex[3+pl+0]*16)*NSQ + 0*g_size*NSQ;
