      gb[4] = (c_lex[3+pj+1]*4 + c_lex[12+pk+1]*8 + c_lex[12+pl+1]*24)*NSQ + 1*g_size*NSQ;
      gb[5] = (c_lex[3+pj+2]*4 + c_lex[12+pk+2]*8 + c_lex[12+pl+2]*24)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+2)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[6] = (c_lex[3+pj+0]*4 + c_lex[12+pk+0]*8 + c_lex[12+pl+0]*24)*NSQ + 0*g_size*NSQ;
      gb[7] = (c_lex[3+pj+1]*4 + c_lex[12+pk+1]*8 + c_lex[12+pl+1]*24)*NSQ + 1*g_size*NSQ;
      gb[8] = (c_lex[3+pj+2]*4 + c_lex[12+pk+2]*8 + c_lex[12+pl+2]*24)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
