      gb[10] = (c_lex[3+pj+1]*4 + c_lex[12+pk+1]*8 + c_lex[12+pl+1]*24)*NSQ + 1*g_size*NSQ;
      gb[11] = (c_lex[3+pj+2]*4 + c_lex[12+pk+2]*8 + c_lex[12+pl+2]*24)*NSQ + 2*g_size*NSQ;
