      gb[16] = (c_lex[3+pj+1]*4 + c_lex[12+pk+1]*8 + c_lex[12+pl+1]*24)*NSQ + 1*g_size*NSQ;
      gb[17] = (c_lex[3+pj+2]*4 + c_lex[12+pk+2]*8 + c_lex[12+pl+2]*24)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+2)*3, pl = (lb_+0)*3;
      gb[18] = (c_lex[3+pj+0]*4 + c_lex[12+pk+0]*8 + c_lex[12+pl+0]*24)*NSQ + 0*g_size*NSQ;
      gb[19] = (c_lex[3+pj+1]*4 + c_lex[12+pk+1]*8 + c_lex[12+pl+1]*24)*NSQ + 1*g_size*NSQ;
      gb[20] = (c_lex[3+pj+2]*4 + c_lex[12+pk+2]*8 + c_lex[12+pl+2]*24)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+1)*3, pk = (kb_+2)*3, pl = (lb_+0)*3;
      gb[21] = (c_lex[3+pj+0]*4 + c_lex[12+pk+0]*8 + c_lex[12+pl+0]*24)*NSQ + 0*g_size*NSQ;
      gb[22] = (c_lex[3+pj+1]*4 + c_lex[12+pk+1]*8 + c_lex[12+pl+1]*24)*NSQ + 1*g_size*NSQ;
      gb[23] = (c_lex[3+pj+2]*4 + c_lex[12+pk+2]*8 + c_lex[12+pl+2]*24)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+2)*3, pk = (kb_+2)*3, pl = (lb_+0)*3;
      gb[24] = (c_lex[3+pj+0]*4 + c_lex[12+pk+0]*8 + c_lex[12+pl+0]*24)*NSQ + 0*g_size*NSQ;
      gb[25] = (c_lex[3+pj+1]*4 + c_lex[12+pk+1]*8 + c_lex[12+pl+1]*24)*NSQ + 1*g_size*NSQ;
      gb[26] = (c_lex[3+pj+2]*4 + c_lex[12+pk+2]*8 + c_lex[12+pl+2]*24)*NSQ + 2*g_size*NSQ;
    }
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += NSQ) {
        __syncthreads();
        int kprim = kprim_a;
