                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[0*NSQ];
                        s1 = cpx * s0;
                        _gx[8*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        _gx[16*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        _gx[24*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 3 * b01 * s0;
                        _gx[32*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[1*NSQ];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0*NSQ];
                        _gx[9*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 1 * b00 * _gx[8*NSQ];
                        _gx[17*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 1 * b00 * _gx[16*NSQ];
                        _gx[25*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 3 * b01 * s0;
                        s2 += 1 * b00 * _gx[24*NSQ];
                        _gx[33*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[2*NSQ];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1*NSQ];
                        _gx[10*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 2 * b00 * _gx[9*NSQ];
                        _gx[18*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 2 * b00 * _gx[17*NSQ];
                        _gx[26*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 3 * b01 * s0;
                        s2 += 2 * b00 * _gx[25*NSQ];
                        _gx[34*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[3*NSQ];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2*NSQ];
                        _gx[11*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 3 * b00 * _gx[10*NSQ];
                        _gx[19*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 3 * b00 * _gx[18*NSQ];
                        _gx[27*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 3 * b01 * s0;
                        s2 += 3 * b00 * _gx[26*NSQ];
                        _gx[35*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[4*NSQ];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[3*NSQ];
                        _gx[12*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 4 * b00 * _gx[11*NSQ];
                        _gx[20*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 4 * b00 * _gx[19*NSQ];
                        _gx[28*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 3 * b01 * s0;
                        s2 += 4 * b00 * _gx[27*NSQ];
                        _gx[36*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s1 = _gx[4*NSQ];
                        s0 = _gx[3*NSQ];
                        _gx[7*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[2*NSQ];
                        _gx[6*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[1*NSQ];
                        _gx[5*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[0*NSQ];
                        _gx[4*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[12*NSQ];
                        s0 = _gx[11*NSQ];
                        _gx[15*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[10*NSQ];
                        _gx[14*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[9*NSQ];
                        _gx[13*NSQ] = s1 - xjxi * s0;
