      gb[10] = (c_lex[3+pj+1]*4 + c_lex[30+pk+1]*8 + c_lex[30+pl+1]*32)*NSQ + 1*g_size*NSQ;
      gb[11] = (c_lex[3+pj+2]*4 + c_lex[30+pk+2]*8 + c_lex[30+pl+2]*32)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+1)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[12] = (c_lex[3+pj+0]*4 + c_lex[30+pk+0]*8 + c_lex[30+pl+0]*32)*NSQ + 0*g_size*NSQ;
      gb[13] = (c_lex[3+pj+1]*4 + c_lex[30+pk+1]*8 + c_lex[30+pl+1]*32)*NSQ + 1*g_size*NSQ;
      gb[14] = (c_lex[3+pj+2]*4 + c_lex[30+pk+2]*8 + c_lex[30+pl+2]*32)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+2)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      gb[15] = (c_lex[3+pj+0]*4 + c_lex[30+pk+0]*8 + c_lex[30+pl+0]*32)*NSQ + 0*g_size*NSQ;
      gb[16] = (c_lex[3+pj+1]*4 + c_lex[30+pk+1]*8 + c_lex[30+pl+1]*32)*NSQ + 1*g_size*NSQ;
      gb[17] = (c_lex[3+pj+2]*4 + c_lex[30+pk+2]*8 + c_lex[30+pl+2]*32)*NSQ + 2*g_size*NSQ;
    }
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += NSQ) {
        __syncthreads();
        int kprim = kprim_a;
        int lprim = lprim_a;
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        if (gout_id == 0) {
            rlrk[0*NSQ] = rl[0] - rk[0];
            rlrk[1*NSQ] = rl[1] - rk[1];
            rlrk[2*NSQ] = rl[2] - rk[2];
            fac_ijkl[0] = fac_sym;
        }
        double gout[60];
#pragma unroll
        for (int n = 0; n < 60; ++n) gout[n] = 0.;

        for (int klp = 0; klp < kprim*lprim; ++klp) {
            __syncthreads();
            if (gout_id == 0) {
                double *expk = env + bas[ksh*BAS_SLOTS+PTR_EXP];
                double *expl = env + bas[lsh*BAS_SLOTS+PTR_EXP];
                double *ck = env + bas[ksh*BAS_SLOTS+PTR_COEFF];
                double *cl = env + bas[lsh*BAS_SLOTS+PTR_COEFF];
                double ak = expk[klp/lprim];
                double al = expl[klp%lprim];
