      gb[7] = (c_lex[12+pj+1]*4 + c_lex[3+pk+1]*12 + c_lex[0+pl+1]*24)*NSQ + 1*g_size*NSQ;
      gb[8] = (c_lex[12+pj+2]*4 + c_lex[3+pk+2]*12 + c_lex[0+pl+2]*24)*NSQ + 2*g_size*NSQ;
