                    const double *gzm5 = gx + gb[17];
                    gout[0] += gxm0[3*NSQ] * gym0[0*NSQ] * gzm0[0*NSQ];
                    gout[1] += gxm0[2*NSQ] * gym0[1*NSQ] * gzm0[0*NSQ];
                    gout[2] += gxm0[2*NSQ] * gym0[0*NSQ] * gzm0[1*NSQ];
