            val += gout[22] * dm[(ii+2)*nao+(llx+0)];
            val += gout[23] * dm[(ii+3)*nao+(llx+0)];
            val += gout[24] * dm[(ii+4)*nao+(llx+0)];
            val += gout[25] * dm[(ii+5)*nao+(llx+0)];
            val += gout[26] * dm[(ii+6)*nao+(llx+0)];
            val += gout[27] * dm[(ii+7)*nao+(llx+0)];
            val += gout[28] * dm[(ii+8)*nao+(llx+0)];
            val += gout[29] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+2)*nao+(kk+0), val);
            val = 0;
            val += gout[30] * dm[(ii+0)*nao+(llx+0)];
            val += gout[31] * dm[(ii+1)*nao+(llx+0)];
            val += gout[32] * dm[(ii+2)*nao+(llx+0)];
            val += gout[33] * dm[(ii+3)*nao+(llx+0)];
            val += gout[34] * dm[(ii+4)*nao+(llx+0)];
            val += gout[35] * dm[(ii+5)*nao+(llx+0)];
            val += gout[36] * dm[(ii+6)*nao+(llx+0)];
            val += gout[37] * dm[(ii+7)*nao+(llx+0)];
            val += gout[38] * dm[(ii+8)*nao+(llx+0)];
            val += gout[39] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+3)*nao+(kk+0), val);
            val = 0;
            val += gout[40] * dm[(ii+0)*nao+(llx+0)];
            val += gout[41] * dm[(ii+1)*nao+(llx+0)];
            val += gout[42] * dm[(ii+2)*nao+(llx+0)];
            val += gout[43] * dm[(ii+3)*nao+(llx+0)];
            val += gout[44] * dm[(ii+4)*nao+(llx+0)];
            val += gout[45] * dm[(ii+5)*nao+(llx+0)];
            val += gout[46] * dm[(ii+6)*nao+(llx+0)];
            val += gout[47] * dm[(ii+7)*nao+(llx+0)];
            val += gout[48] * dm[(ii+8)*nao+(llx+0)];
            val += gout[49] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+4)*nao+(kk+0), val);
            val = 0;
            val += gout[50] * dm[(ii+0)*nao+(llx+0)];
            val += gout[51] * dm[(ii+1)*nao+(llx+0)];
            val += gout[52] * dm[(ii+2)*nao+(llx+0)];
            val += gout[53] * dm[(ii+3)*nao+(llx+0)];
            val += gout[54] * dm[(ii+4)*nao+(llx+0)];
            val += gout[55] * dm[(ii+5)*nao+(llx+0)];
            val += gout[56] * dm[(ii+6)*nao+(llx+0)];
            val += gout[57] * dm[(ii+7)*nao+(llx+0)];
            val += gout[58] * dm[(ii+8)*nao+(llx+0)];
            val += gout[59] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+5)*nao+(kk+0), val);
        }
    }
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


// ---- (3220) : 360 gout over 6 lanes, 32 shell quartets per block
#define NTHREADS_3220 192
#define MINBLOCKS_3220 1
extern "C" __global__ void __launch_bounds__(NTHREADS_3220, MINBLOCKS_3220)
kh_3220(KARGS2)
{
    constexpr int NSQ = 32;
    constexpr int GSTRIDE = 6;
    constexpr int NROOTS = 4;
    constexpr int g_size = 36;
    constexpr int nsq_per_block = NSQ;
    __shared__ double s_aij[36], s_iaij[36], s_ajaij[36];
    __shared__ double s_xij[36], s_yij[36], s_zij[36];
    __shared__ double s_cicj[36];

    int sq_id = threadIdx.x;
    int gout_id = threadIdx.y;
    int thread_id = NSQ * gout_id + sq_id;
    constexpr int threads = NSQ * GSTRIDE;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    __shared__ int ntasks, pair_ij;
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
    }
    __syncthreads();
    fill_vk_tasks2(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff);
    if (ntasks == 0) {
        if (thread_id == 0) {
            pair_ij = atomicAdd(head, 1);
        }
        __syncthreads();
        continue;
    }

    extern __shared__ double shared_memory[];
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + NSQ * 3 + sq_id;
    double *akl_cache = shared_memory + NSQ * 6 + sq_id;
    double *fac_ijkl = shared_memory + NSQ * 9 + sq_id;
    double *gx = shared_memory + NSQ * 10 + sq_id;
    double *rw = shared_memory + NSQ * (g_size*3+10) + sq_id;

    __shared__ int ish, jsh;
    __shared__ double ri[3], rjri[3];
    __shared__ double *expi;
    __shared__ double *expj;
    if (thread_id == 0) {
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
        expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a;
    int jprim = jprim_a;
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
    for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
        double ai = expi[ij/jprim];
        double aj = expj[ij%jprim];
        double aij = ai + aj;
        double iaij = 1. / aij;
        double aj_aij = aj * iaij;
        s_aij  [ij] = aij;
        s_iaij [ij] = iaij;
        s_ajaij[ij] = aj_aij;
        s_xij  [ij] = ri[0] + rjri[0] * aj_aij;
        s_yij  [ij] = ri[1] + rjri[1] * aj_aij;
        s_zij  [ij] = ri[2] + rjri[2] * aj_aij;
        s_cicj [ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
    }
    __syncthreads();
    int o_base = gout_id * 6;
    int jb_ = o_base % 6;
    int kb_ = (o_base / 6) % 6;
    int lb_ = o_base / 36;
    int gb[18];
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[0] = (c_lex[12+pj+0]*4 + c_lex[12+pk+0]*12 + c_lex[0+pl+0]*36)*NSQ + 0*g_size*NSQ;
      gb[1] = (c_lex[12+pj+1]*4 + c_lex[12+pk+1]*12 + c_lex[0+pl+1]*36)*NSQ + 1*g_size*NSQ;
      gb[2] = (c_lex[12+pj+2]*4 + c_lex[12+pk+2]*12 + c_lex[0+pl+2]*36)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+1)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[3] = (c_lex[12+pj+0]*4 + c_lex[12+pk+0]*12 + c_lex[0+pl+0]*36)*NSQ + 0*g_size*NSQ;
      gb[4] = (c_lex[12+pj+1]*4 + c_lex[12+pk+1]*12 + c_lex[0+pl+1]*36)*NSQ + 1*g_size*NSQ;
      gb[5] = (c_lex[12+pj+2]*4 + c_lex[12+pk+2]*12 + c_lex[0+pl+2]*36)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+2)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[6] = (c_lex[12+pj+0]*4 + c_lex[12+pk+0]*12 + c_lex[0+pl+0]*36)*NSQ + 0*g_size*NSQ;
      gb[7] = (c_lex[12+pj+1]*4 + c_lex[12+pk+1]*12 + c_lex[0+pl+1]*36)*NSQ + 1*g_size*NSQ;
      gb[8] = (c_lex[12+pj+2]*4 + c_lex[12+pk+2]*12 + c_lex[0+pl+2]*36)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+3)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[9] = (c_lex[12+pj+0]*4 + c_lex[12+pk+0]*12 + c_lex[0+pl+0]*36)*NSQ + 0*g_size*NSQ;
      gb[10] = (c_lex[12+pj+1]*4 + c_lex[12+pk+1]*12 + c_lex[0+pl+1]*36)*NSQ + 1*g_size*NSQ;
      gb[11] = (c_lex[12+pj+2]*4 + c_lex[12+pk+2]*12 + c_lex[0+pl+2]*36)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+4)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[12] = (c_lex[12+pj+0]*4 + c_lex[12+pk+0]*12 + c_lex[0+pl+0]*36)*NSQ + 0*g_size*NSQ;
      gb[13] = (c_lex[12+pj+1]*4 + c_lex[12+pk+1]*12 + c_lex[0+pl+1]*36)*NSQ + 1*g_size*NSQ;
      gb[14] = (c_lex[12+pj+2]*4 + c_lex[12+pk+2]*12 + c_lex[0+pl+2]*36)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+5)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[15] = (c_lex[12+pj+0]*4 + c_lex[12+pk+0]*12 + c_lex[0+pl+0]*36)*NSQ + 0*g_size*NSQ;
      gb[16] = (c_lex[12+pj+1]*4 + c_lex[12+pk+1]*12 + c_lex[0+pl+1]*36)*NSQ + 1*g_size*NSQ;
      gb[17] = (c_lex[12+pj+2]*4 + c_lex[12+pk+2]*12 + c_lex[0+pl+2]*36)*NSQ + 2*g_size*NSQ;
    }
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += NSQ) {
        __syncthreads();
        int kprim = kprim_a;
        int lprim = lprim_a;
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        if (gout_id == 0) {
            rlrk[0*NSQ] = rl[0] - rk[0];
            rlrk[1*NSQ] = rl[1] - rk[1];
            rlrk[2*NSQ] = rl[2] - rk[2];
            fac_ijkl[0] = fac_sym;
        }
        double gout[60];
#pragma unroll
        for (int n = 0; n < 60; ++n) gout[n] = 0.;

        for (int klp = 0; klp < kprim*lprim; ++klp) {
            __syncthreads();
            if (gout_id == 0) {
                double *expk = env + bas[ksh*BAS_SLOTS+PTR_EXP];
                double *expl = env + bas[lsh*BAS_SLOTS+PTR_EXP];
                double *ck = env + bas[ksh*BAS_SLOTS+PTR_COEFF];
                double *cl = env + bas[lsh*BAS_SLOTS+PTR_COEFF];
                double ak = expk[klp/lprim];
                double al = expl[klp%lprim];
                double akl = ak + al;
                double iakl = 1. / akl;
                double al_akl = al * iakl;
                double xlxk = rlrk[0*NSQ], ylyk = rlrk[1*NSQ], zlzk = rlrk[2*NSQ];
                double Kcd = exp(-ak * al_akl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                gx[0] = fac_ijkl[0] * ck[klp/lprim] * cl[klp%lprim] * Kcd;
                akl_cache[0*NSQ] = akl;
                akl_cache[1*NSQ] = al_akl;
                akl_cache[2*NSQ] = iakl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                __syncthreads();
                double aij = s_aij[ijp];
                double iaij = s_iaij[ijp];
                double akl = akl_cache[0*NSQ];
                double al_akl = akl_cache[1*NSQ];
                double iakl = akl_cache[2*NSQ];
                // Range separation: inv_om2 = 0 is the full-range operator,
                // 1/omega^2 the long-range (erf) one -- scaling the Rys
                // argument and roots by w^2/(w^2+theta) is exactly
                // rsqrt(s) -> rsqrt(s + aij*akl/w^2) here.
                double inv_s = rsqrt(fma(aij * akl, inv_om2, aij + akl));
                double inv_s2 = inv_s * inv_s;
                double xkl = rk[0] + rlrk[0*NSQ] * al_akl;
                double ykl = rk[1] + rlrk[1*NSQ] * al_akl;
                double zkl = rk[2] + rlrk[2*NSQ] * al_akl;
                double xpq = s_xij[ijp] - xkl;
                double ypq = s_yij[ijp] - ykl;
                double zpq = s_zij[ijp] - zkl;
                if (gout_id == 0) {
                    Rpq[0*NSQ] = xpq;
                    Rpq[1*NSQ] = ypq;
                    Rpq[2*NSQ] = zpq;
                    // fac = cicj*ckcl/(aij*akl*sqrt(aij+akl)), no division
                    gx[NSQ*g_size] = s_cicj[ijp] * iaij * iakl * inv_s * coef0;
                }
                double rr = xpq*xpq + ypq*ypq + zpq*zpq;
                rys_roots_tab<NROOTS>(aij*akl*inv_s2 * rr, rw, NSQ, gout_id,
                                      GSTRIDE, tab);
                for (int irys = 0; irys < NROOTS; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[2*irys*NSQ];
                    double rt_aa = rt * inv_s2;
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5*iaij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5*iakl * (1 - rt_akl);
                    (void)b10; (void)b00; (void)b01;
                    for (int n = gout_id; n < 3; n += GSTRIDE) {
                        if (n == 2) { gx[2*g_size*NSQ] = rw[(2*irys+1)*NSQ]; }
                        double *_gx = gx + n * g_size * NSQ;
                        double xjxi = rjri[n], xlxk = rlrk[n*NSQ];
                        double c0x = xjxi * s_ajaij[ijp] - rt_aij * Rpq[n*NSQ];
                        double cpx = xlxk * al_akl + rt_akl * Rpq[n*NSQ];
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = _gx[0*NSQ];
                        s1 = c0x * s0;
                        _gx[1*NSQ] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 4 * b10 * s0;
                        _gx[5*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[0*NSQ];
                        s1 = cpx * s0;
                        _gx[12*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        _gx[24*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[1*NSQ];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0*NSQ];
                        _gx[13*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 1 * b00 * _gx[12*NSQ];
                        _gx[25*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[2*NSQ];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1*NSQ];
                        _gx[14*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 2 * b00 * _gx[13*NSQ];
                        _gx[26*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[3*NSQ];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2*NSQ];
                        _gx[15*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 3 * b00 * _gx[14*NSQ];
                        _gx[27*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[4*NSQ];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[3*NSQ];
                        _gx[16*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 4 * b00 * _gx[15*NSQ];
                        _gx[28*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[5*NSQ];
                        s1 = cpx * s0;
                        s1 += 5 * b00 * _gx[4*NSQ];
                        _gx[17*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 5 * b00 * _gx[16*NSQ];
                        _gx[29*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s1 = _gx[5*NSQ];
                        s0 = _gx[4*NSQ];
                        _gx[8*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[3*NSQ];
                        _gx[7*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[2*NSQ];
                        _gx[6*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[1*NSQ];
                        _gx[5*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[0*NSQ];
                        _gx[4*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[8*NSQ];
                        s0 = _gx[7*NSQ];
                        _gx[11*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[6*NSQ];
                        _gx[10*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[5*NSQ];
                        _gx[9*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[4*NSQ];
                        _gx[8*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[17*NSQ];
                        s0 = _gx[16*NSQ];
                        _gx[20*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[15*NSQ];
                        _gx[19*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[14*NSQ];
                        _gx[18*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[13*NSQ];
                        _gx[17*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[12*NSQ];
                        _gx[16*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[20*NSQ];
                        s0 = _gx[19*NSQ];
                        _gx[23*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[18*NSQ];
                        _gx[22*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[17*NSQ];
                        _gx[21*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[16*NSQ];
                        _gx[20*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[29*NSQ];
                        s0 = _gx[28*NSQ];
                        _gx[32*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[27*NSQ];
                        _gx[31*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[26*NSQ];
                        _gx[30*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[25*NSQ];
                        _gx[29*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[24*NSQ];
                        _gx[28*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[32*NSQ];
                        s0 = _gx[31*NSQ];
                        _gx[35*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[30*NSQ];
                        _gx[34*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[29*NSQ];
                        _gx[33*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[28*NSQ];
                        _gx[32*NSQ] = s1 - xjxi * s0;
                        s1 = s0;
                    }
                    __syncthreads();
                    const double *gxm0 = gx + gb[0];
                    const double *gym0 = gx + gb[1];
                    const double *gzm0 = gx + gb[2];
                    const double *gxm1 = gx + gb[3];
