                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1*NSQ];
                        _gx[14*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 2 * b00 * _gx[13*NSQ];
                        _gx[26*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 2 * b00 * _gx[25*NSQ];
                        _gx[38*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 3 * b01 * s0;
                        s2 += 2 * b00 * _gx[37*NSQ];
                        _gx[50*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 4 * b01 * s0;
                        s2 += 2 * b00 * _gx[49*NSQ];
                        _gx[62*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[3*NSQ];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2*NSQ];
                        _gx[15*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 3 * b00 * _gx[14*NSQ];
                        _gx[27*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 3 * b00 * _gx[26*NSQ];
                        _gx[39*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 3 * b01 * s0;
                        s2 += 3 * b00 * _gx[38*NSQ];
                        _gx[51*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 4 * b01 * s0;
