                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 4 * b00 * _gx[15*NSQ];
                        _gx[28*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 4 * b00 * _gx[27*NSQ];
                        _gx[40*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 3 * b01 * s0;
                        s2 += 4 * b00 * _gx[39*NSQ];
                        _gx[52*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 4 * b01 * s0;
                        s2 += 4 * b00 * _gx[51*NSQ];
                        _gx[64*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[5*NSQ];
                        s1 = cpx * s0;
                        s1 += 5 * b00 * _gx[4*NSQ];
                        _gx[17*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 5 * b00 * _gx[16*NSQ];
                        _gx[29*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 5 * b00 * _gx[28*NSQ];
                        _gx[41*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
