                        s0 = _gx[0*NSQ];
                        s1 = c0x * s0;
                        _gx[1*NSQ] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 4 * b10 * s0;
                        _gx[5*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 5 * b10 * s0;
                        _gx[6*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[0*NSQ];
                        s1 = cpx * s0;
                        _gx[16*NSQ] = s1;
                        s0 = _gx[1*NSQ];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0*NSQ];
                        _gx[17*NSQ] = s1;
                        s0 = _gx[2*NSQ];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1*NSQ];
                        _gx[18*NSQ] = s1;
                        s0 = _gx[3*NSQ];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2*NSQ];
                        _gx[19*NSQ] = s1;
                        s0 = _gx[4*NSQ];
