      gb[13] = (c_lex[30+pj+1]*4 + c_lex[12+pk+1]*16 + c_lex[0+pl+1]*48)*NSQ + 1*g_size*NSQ;
      gb[14] = (c_lex[30+pj+2]*4 + c_lex[12+pk+2]*16 + c_lex[0+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
