            val += gout[18] * dm[(ii+8)*nao+(llx+0)];
            val += gout[19] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+1)*nao+(kk+0), val);
            val = 0;
            val += gout[20] * dm[(ii+0)*nao+(llx+0)];
            val += gout[21] * dm[(ii+1)*nao+(llx+0)];
