            val += gout[28] * dm[(ii+8)*nao+(llx+0)];
            val += gout[29] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+2)*nao+(kk+0), val);
            val = 0;
            val += gout[30] * dm[(ii+0)*nao+(llx+0)];
            val += gout[31] * dm[(ii+1)*nao+(llx+0)];
            val += gout[32] * dm[(ii+2)*nao+(llx+0)];
            val += gout[33] * dm[(ii+3)*nao+(llx+0)];
            val += gout[34] * dm[(ii+4)*nao+(llx+0)];
            val += gout[35] * dm[(ii+5)*nao+(llx+0)];
            val += gout[36] * dm[(ii+6)*nao+(llx+0)];
            val += gout[37] * dm[(ii+7)*nao+(llx+0)];
            val += gout[38] * dm[(ii+8)*nao+(llx+0)];
            val += gout[39] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+3)*nao+(kk+0), val);
            val = 0;
            val += gout[40] * dm[(ii+0)*nao+(llx+0)];
            val += gout[41] * dm[(ii+1)*nao+(llx+0)];
            val += gout[42] * dm[(ii+2)*nao+(llx+0)];
            val += gout[43] * dm[(ii+3)*nao+(llx+0)];
            val += gout[44] * dm[(ii+4)*nao+(llx+0)];
            val += gout[45] * dm[(ii+5)*nao+(llx+0)];
            val += gout[46] * dm[(ii+6)*nao+(llx+0)];
            val += gout[47] * dm[(ii+7)*nao+(llx+0)];
            val += gout[48] * dm[(ii+8)*nao+(llx+0)];
            val += gout[49] * dm[(ii+9)*nao+(llx+0)];
            atomicAdd(vk+(jj+4)*nao+(kk+0), val);
        }
    }
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


// ---- (3321) : 1800 gout over 36 lanes, 4 shell quartets per block
#define NTHREADS_3321 144
#define MINBLOCKS_3321 1
extern "C" __global__ void __launch_bounds__(NTHREADS_3321, MINBLOCKS_3321)
kh_3321(KARGS2)
{
    constexpr int NSQ = 4;
    constexpr int GSTRIDE = 36;
    constexpr int NROOTS = 5;
    constexpr int g_size = 96;
    constexpr int nsq_per_block = NSQ;
    __shared__ double s_aij[36], s_iaij[36], s_ajaij[36];
    __shared__ double s_xij[36], s_yij[36], s_zij[36];
    __shared__ double s_cicj[36];

    int sq_id = threadIdx.x;
    int gout_id = threadIdx.y;
    int thread_id = NSQ * gout_id + sq_id;
    constexpr int threads = NSQ * GSTRIDE;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    __shared__ int ntasks, pair_ij;
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
    }
    __syncthreads();
    fill_vk_tasks2(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff);
    if (ntasks == 0) {
        if (thread_id == 0) {
            pair_ij = atomicAdd(head, 1);
        }
        __syncthreads();
        continue;
    }

    extern __shared__ double shared_memory[];
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + NSQ * 3 + sq_id;
    double *akl_cache = shared_memory + NSQ * 6 + sq_id;
    double *fac_ijkl = shared_memory + NSQ * 9 + sq_id;
    double *gx = shared_memory + NSQ * 10 + sq_id;
    double *rw = shared_memory + NSQ * (g_size*3+10) + sq_id;

    __shared__ int ish, jsh;
    __shared__ double ri[3], rjri[3];
    __shared__ double *expi;
    __shared__ double *expj;
    if (thread_id == 0) {
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
        expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a;
    int jprim = jprim_a;
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
    for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
        double ai = expi[ij/jprim];
        double aj = expj[ij%jprim];
        double aij = ai + aj;
        double iaij = 1. / aij;
        double aj_aij = aj * iaij;
        s_aij  [ij] = aij;
        s_iaij [ij] = iaij;
        s_ajaij[ij] = aj_aij;
        s_xij  [ij] = ri[0] + rjri[0] * aj_aij;
        s_yij  [ij] = ri[1] + rjri[1] * aj_aij;
        s_zij  [ij] = ri[2] + rjri[2] * aj_aij;
        s_cicj [ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
    }
    __syncthreads();
    int o_base = gout_id * 5;
    int jb_ = o_base % 10;
    int kb_ = (o_base / 10) % 6;
    int lb_ = o_base / 60;
    int gb[15];
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[0] = (c_lex[30+pj+0]*4 + c_lex[12+pk+0]*16 + c_lex[3+pl+0]*48)*NSQ + 0*g_size*NSQ;
      gb[1] = (c_lex[30+pj+1]*4 + c_lex[12+pk+1]*16 + c_lex[3+pl+1]*48)*NSQ + 1*g_size*NSQ;
      gb[2] = (c_lex[30+pj+2]*4 + c_lex[12+pk+2]*16 + c_lex[3+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+1)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[3] = (c_lex[30+pj+0]*4 + c_lex[12+pk+0]*16 + c_lex[3+pl+0]*48)*NSQ + 0*g_size*NSQ;
      gb[4] = (c_lex[30+pj+1]*4 + c_lex[12+pk+1]*16 + c_lex[3+pl+1]*48)*NSQ + 1*g_size*NSQ;
      gb[5] = (c_lex[30+pj+2]*4 + c_lex[12+pk+2]*16 + c_lex[3+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+2)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[6] = (c_lex[30+pj+0]*4 + c_lex[12+pk+0]*16 + c_lex[3+pl+0]*48)*NSQ + 0*g_size*NSQ;
      gb[7] = (c_lex[30+pj+1]*4 + c_lex[12+pk+1]*16 + c_lex[3+pl+1]*48)*NSQ + 1*g_size*NSQ;
      gb[8] = (c_lex[30+pj+2]*4 + c_lex[12+pk+2]*16 + c_lex[3+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+3)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
