      gb[10] = (c_lex[30+pj+1]*4 + c_lex[12+pk+1]*16 + c_lex[3+pl+1]*48)*NSQ + 1*g_size*NSQ;
      gb[11] = (c_lex[30+pj+2]*4 + c_lex[12+pk+2]*16 + c_lex[3+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+4)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      gb[12] = (c_lex[30+pj+0]*4 + c_lex[12+pk+0]*16 + c_lex[3+pl+0]*48)*NSQ + 0*g_size*NSQ;
      gb[13] = (c_lex[30+pj+1]*4 + c_lex[12+pk+1]*16 + c_lex[3+pl+1]*48)*NSQ + 1*g_size*NSQ;
      gb[14] = (c_lex[30+pj+2]*4 + c_lex[12+pk+2]*16 + c_lex[3+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += NSQ) {
        __syncthreads();
        int kprim = kprim_a;
